}.base-lights{position:absolute;left:calc(50% - 44px);bottom:43px;display:flex;gap:23px}.base-lights i{width:8px;height:8px;background:var(--lime);border-radius:50%;box-shadow:0 0 12px var(--lime)}.base-info{display:flex;justify-content:space-between;align-items:center}.base-info b{font:600 12px var(--display)}.base-info span{font:9px var(--mono);color:var(--lime)}.base-meta{color:#85868b;font-size:10px;margin-top:4px}.activity-item{display:flex;gap:10px;padding:11px 0;border-bottom:1px solid #2b2c31;align-items:center}.activity-item:last-child{border:0}.activity-avatar{width:30px;height:30px;background:#2c2d31;border-radius:50%;display:grid;place-items:center}.activity-text{font-size:10px;color:#a3a3a7;line-height:1.5;flex:1}.activity-text b{color:#e5e3dd}.activity-time{color:#75767c;font:9px var(--mono);white-space:nowrap}

