ct-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 10px 8px #0008)}.encounter-scene .enemy{width:174px;height:174px}.battle-status{z-index:2;align-self:start;background:#131416dd;padding:12px;border-radius:7px;border:1px solid #ffffff1a}.battle-status b{display:block;font:600 13px var(--display)}.battle-status small{display:block;margin-top:5px;color:#b2b2ad;font:9px var(--mono)}.hpbar{height:5px;background:#48433c;border-radius:8px;margin-top:10px;overflow:hidden}.hpbar i{display:block;height:100%;width:100%;background:#d6e76b;transition:width .5s}.player-status{z-index:2;align-self:end;justify-self:end;text-align:right;background:#131416dd;padding:12px;border-radius:7px;border:1px solid #ffffff1a}.player-status b{font:600 12px var(--display)}.battle-log{min-height:48px;padding:14px 18px;color:#bbbcc0;font-size:11px;border-bottom:1px solid var(--line)}.battle-actions{padding:14px 18px 18px}.battle-actions h4{font:600 11px var(--display);margin:0 0 11px}.action-row{display:flex;gap:8px;flex-wrap:wrap}.action-btn{background:#27282d;border:1px solid #3a3b40;border-radius:7px;padding:10px 13px;font-size:10px;transition:.15s}.action-btn:hover{border-color:var(--lime);color:var(--lime)}.action-btn.selected{border-color:var(--lime);background:#d8f36a14;color:var(--lime)}.action-btn:disabled{opacity:.45;cursor:default}.result-panel{text-align:center;padding:32px 20px}.result-panel .result-emoji{font-size:48px}.result-panel h2{font:700 23px var(--display);margin:12px 0 7px}.result-panel p{color:#a2a3a8;font-size:12px;line-height:1.6}.result-panel .primary-btn{margin-top:13px}.reward-pills{display:flex;justify-content:center;gap:8px;margin:17px}.reward-pills span{font:10px var(--mono);padding:7px 9px;border-radius:20px;background:#292a2f;color:var(--lime)}.upgrade-list{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.upgrade{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:15px;position:relative}.upgrade-icon{width:36px;hei