-mono);color:var(--lime)}.toast{position:fixed;z-index:30;bottom:24px;left:50%;transform:translate(-50%,20px);padding:11px 16px;border:1px solid #484a3b;background:#24251f;border-radius:8px;color:#e3e7d2;font-size:11px;opacity:0;pointer-events:none;transition:.25s;box-shadow:0 8px 30px #0008}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-menu{display:none}
