const SPRITE='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/';
const ranks=[{name:'Grunt',need:0,mark:'I'},{name:'Runner',need:2,mark:'II'},{name:'Agent',need:5,mark:'III'},{name:'Specialist',need:9,mark:'IV'},{name:'Executive',need:14,mark:'V'},{name:'Boss',need:20,mark:'VI'}];
const missions=[
 {id:'route',icon:'🌿',name:'Viridian Outskirts',place:'KANTO · ROUTE 2',desc:'Low-risk scouting run. The locals barely know we’re here.',rank:0,reward:24,pokemon:[{name:'Caterpie',id:10,type:'Bug',rarity:1},{name:'Pidgey',id:16,type:'Normal',rarity:1},{name:'Rattata',id:19,type:'Normal',rarity:1},{name:'Nidoran♀',id:29,type:'Poison',rarity:2}]},
 {id:'coast',icon:'🌊',name:'Cerulean Coast',place:'KANTO · ROUTE 24',desc:'Rare water types have been spotted near the cape. Bring extra capsules.',rank:1,reward:42,pokemon:[{name:'Psyduck',id:54,type:'Water',rarity:2},{name:'Horsea',id:116,type:'Water',rarity:2},{name:'Magikarp',id:129,type:'Water',rarity:1},{name:'Abra',id:63,type:'Psychic',rarity:3}]},
 {id:'power',icon:'⚡',name:'Power Plant Sweep',place:'KANTO · ROUTE 10',desc:'High voltage, high value. The plant is crawling with powerful Pokémon.',rank:2,reward:68,pokemon:[{name:'Magnemite',id:81,type:'Electric',rarity:3},{name:'Voltorb',id:100,type:'Electric',rarity:2},{name:'Electabuzz',id:125,type:'Electric',rarity:4},{name:'Pikachu',id:25,type:'Electric',rarity:4}]},
 {id:'cave',icon:'🌙',name:'Mt. Moon After Dark',place:'KANTO · MT. MOON',desc:'A secretive cave operation. Rare fossils and rarer company.',rank:3,reward:95,pokemon:[{name:'Zubat',id:41,type:'Poison',rarity:2},{name:'Clefairy',id:35,type:'Fairy',rarity:3},{name:'Onix',id:95,type:'Rock',rarity:4},{name:'Geodude',id:74,type:'Rock',rarity:2}]},
 {id:'league',icon:'🏆',name:'Indigo League Infiltration',place:'KANTO · INDIGO PLATEAU',desc:'The ultimate score. Only a Rocket boss gets clearance for this one.',rank:5,reward:180,pokemon:[{name:'Dragonite',id:149,type:'Dragon',rarity:5},{name:'Snorlax',id:143,type:'Normal',rarity:5},{name:'Gengar',id:94,type:'Ghost',rarity:5},{name:'Charizard',id:6,type:'Fire',rarity:5}]}
];
const upgrades=[
 {id:'quarters',icon:'🛏️',name:'Rocket Quarters',desc:'A proper place for the crew to rest between operations.',rank:0,cost:0,effect:'Base essential',start:true},
 {id:'gear',icon:'🎯',name:'Capture Lab',desc:'Refined capsules increase your chance to bring targets home.',rank:1,cost:90,effect:'+12% capture chance'},
 {id:'intel',icon:'🛰️',name:'Intel Room',desc:'Better field intel means better-paying operations.',rank:2,cost:150,effect:'+10 credits per mission'},
 {id:'training',icon:'🥊',name:'Training Floor',desc:'A stronger crew can wear down wild targets faster.',rank:3,cost:220,effect:'+15% capture chance'},
 {id:'expansion',icon:'🏢',name:'HQ Expansion',desc:'Boss-only: expand the hideout, add a new wing, and make room for a bigger operation.',rank:5,cost:180,effect:'Expand your base · level 0 / 3',expand:true}
];
const fresh=()=>({version:1,view:'dashboard',credits:120,captures:0,rep:0,team:[],owned:['quarters'],expansion:0,activity:[],encounter:null});
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem('rocket-ranks-save')||'{}')};state.team=state.team||[];state.owned=state.owned||['quarters'];state.activity=state.activity||[]}catch{state=fresh()}
const rankIndex=()=>{let idx=0;for(let i=0;i<ranks.length;i++)if(state.captures>=ranks[i].need)idx=i;return idx};
const rankName=()=>ranks[rankIndex()].name;
const rankProgress=()=>{const i=rankIndex(),cur=ranks[i].need,next=ranks[i+1]?.need;if(next===undefined)return 100;return Math.min(100,(state.captures-cur)/(next-cur)*100)};
function save(){localStorage.setItem('rocket-ranks-save',JSON.stringify(state))}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function sprite(id){return `${SPRITE}${id}.png`}
function addActivity(text,icon='📡'){state.activity.unshift({text,icon,time:'just now'});state.activity=state.activity.slice(0,5)}
let toastTimer;function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
const navItems=[['dashboard','⌂','Overview'],['operations','◎','Operations'],['base','▦','Base HQ'],['roster','◈','Collection']];
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">R</div><div class="brand-name">ROCKET RANKS<span>TEAM ROCKET COMMAND</span></div></div><div class="nav-label">COMMAND DECK</div><nav class="nav">${navItems.map(([id,ico,label])=>`<button class="nav-btn ${state.view===id||state.view==='encounter'&&id==='operations'?'active':''}" data-view="${id}"><span class="nav-icon">${ico}</span>${label}${id==='roster'?`<span class="nav-count">${state.team.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="rank-mini"><div class="mini-top"><span>${rankName()} RANK</span><span>${state.captures} / ${ranks[rankIndex()+1]?.need??'MAX'}</span></div><div class="mini-sub">FIELD OPERATIVE · KANTO</div><div class="track"><i style="width:${rankProgress()}%"></i></div></div><div class="side-footer"><span><i class="online-dot">●</i> HQ NETWORK</span><span>v1.04</span></div></div></aside><main class="main"><header class="topbar"><div class="crumb">TEAM ROCKET&nbsp; / &nbsp;<b>${state.view==='dashboard'?'COMMAND CENTER':state.view==='operations'||state.view==='encounter'?'FIELD OPERATIONS':state.view==='base'?'HEADQUARTERS':state.view==='roster'?'POKÉDEX':'COMMAND CENTER'}</b></div><div class="top-right"><div class="currency"><span class="coin">◈</span><span>${state.credits.toLocaleString()} CR</span></div><div class="profile" title="${rankName()}">R</div></div></header>${content}</main></div>`}
function head(title,subtitle,kicker='TEAM ROCKET · KANTO DIVISION'){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><span class="date-tag">OPERATIVE ${String(state.captures+1).padStart(3,'0')}</span></div>`}
function dashboard(){const recent=state.activity.length?state.activity.slice(0,3):[{text:'Your field file is open. Awaiting first operation.',icon:'📡',time:'now'}];const lead=missions[rankIndex()>=5?4:Math.min(rankIndex(),2)];return `${head('Command center','Good to see you, rookie. The boss expects results.')}
<div class="dashboard-grid"><section class="hero"><div class="hero-bg"></div><img class="hero-art" src="${sprite(52)}" alt="Meowth"/><div class="hero-content"><span class="mission-tag">● &nbsp;${lead.place} · ACTIVE INTEL</span><h2>Make them an offer they can’t refuse.</h2><p>Go out, find a rare Pokémon, and bring it back to HQ. That’s how you make a name around here.</p><div class="hero-bottom"><button class="primary-btn" data-view="operations">Launch operation <span>↗</span></button><span class="hero-reward">PAYOUT &nbsp;<b>◈ ${lead.reward}+ CR</b></span></div></div></section>
<section class="briefing"><div class="section-heading"><h3>Mission briefing</h3><span>INCOMING</span></div><div class="intel-row"><div class="intel-icon">🎯</div><div class="intel-copy"><b>Primary objective</b><small>Capture wild Pokémon</small></div><span class="intel-value">+ REP</span></div><div class="intel-row"><div class="intel-icon">🗺️</div><div class="intel-copy"><b>Field location</b><small>${lead.place}</small></div><span class="intel-value">${lead.icon}</span></div><div class="intel-row"><div class="intel-icon">⚠️</div><div class="intel-copy"><b>Threat level</b><small>${['Low','Moderate','High','Severe','Extreme'][Math.min(4,lead.rank)]}</small></div><span class="intel-value">${'★'.repeat(Math.min(5,lead.rank+1))}</span></div><div class="briefing-foot"><span>HANDLER</span><b>EXECUTIVE M. · TEAM ROCKET</b></div></section></div>
<div class="stats"><div class="stat"><div class="stat-top">CURRENT RANK <span class="stat-icon">♜</span></div><div class="stat-value">${rankName()}</div><div class="stat-caption">${rankIndex()===5?'The boss answers to no one.':`${ranks[rankIndex()+1].need-state.captures} captures to promotion`}</div></div><div class="stat"><div class="stat-top">POKÉMON SECURED <span class="stat-icon">◈</span></div><div class="stat-value">${state.captures}</div><div class="stat-caption">${state.team.length} in your collection</div></div><div class="stat"><div class="stat-top">FIELD CREDITS <span class="stat-icon">◉</span></div><div class="stat-value">${state.credits.toLocaleString()}</div><div class="stat-caption">Ready to invest in HQ</div></div><div class="stat"><div class="stat-top">BASE LEVEL <span class="stat-icon">⌂</span></div><div class="stat-value">${1+state.expansion}<span style="font-size:13px;color:#8f9096"> / ${rankIndex()===5?4:1+Math.floor(rankIndex()/2)}</span></div><div class="stat-caption">${state.expansion?'Expanded hideout':'Kanto hideout'}</div></div></div>
<div class="bottom-grid"><section class="base-card"><div class="section-title"><h2>Our hideout</h2><button class="text-link" data-view="base">MANAGE BASE ↗</button></div><div class="base-visual" style="--expand:${state.expansion}"><div class="mountain m1"></div><div class="mountain m2"></div><div class="base-building" style="width:${139+state.expansion*23}px;height:${82+state.expansion*9}px"></div><div class="base-lights"><i></i><i></i><i></i></div><div class="base-ground"></div></div><div class="base-info"><div><b>${state.expansion?'Expanded Rocket HQ':'Kanto Hideout'}</b><div class="base-meta">${state.owned.length} facility${state.owned.length===1?'':'ies'} operational</div></div><span>● ACTIVE</span></div></section><section class="activity-card"><div class="section-title"><h2>Field reports</h2><span class="text-link">LIVE FEED</span></div>${recent.map(a=>`<div class="activity-item"><div class="activity-avatar">${a.icon}</div><div class="activity-text">${a.text}</div><span class="activity-time">${a.time}</span></div>`).join('')}</section></div>`}
function operations(){return `${head('Field operations','Pick a location, make a clean capture, and earn your stripes.')}
<div class="view-grid"><section class="panel"><h3>Available assignments</h3><p class="panel-sub">Missions unlock as you prove yourself to the organization.</p><div class="mission-list">${missions.map(m=>{const locked=rankIndex()<m.rank;return `<article class="mission-card ${locked?'locked':''}"><div class="mission-badge">${m.icon}</div><main><h4>${m.name}</h4><p>${m.desc}</p><div class="mission-meta"><span>${m.place}</span><b>◈ ${m.reward} CR</b><span>THREAT ${'★'.repeat(Math.min(5,m.rank+1))}</span></div></main><button class="primary-btn" data-mission="${m.id}" ${locked?'disabled':''}>${locked?`🔒 Rank ${ranks[m.rank].name}`:'Deploy ↗'}</button></article>`}).join('')}</div><div class="panel-note">FIELD TIP &nbsp;·&nbsp; A careful approach can improve your odds. Weaken a target before throwing a capsule, and the Capture Lab helps too.</div></section><aside class="panel"><h3>Promotion track</h3><p class="panel-sub">Earn promotions by securing Pokémon in the field.</p><div class="rank-list">${ranks.map((r,i)=>`<div class="intel-row"><div class="intel-icon" style="font:11px var(--mono);color:${rankIndex()>=i?'var(--lime)':'#85858b'}">${i<rankIndex()?'✓':r.mark}</div><div class="intel-copy"><b style="color:${rankIndex()===i?'var(--lime)':''}">${r.name}${i===rankIndex()?' · YOU':''}</b><small>${r.need===0?'Your story starts here':`${r.need} captures required`}</small></div><span class="intel-value">${rankIndex()>=i?'✓':`#${r.need}`}</span></div>`).join('')}</div><div class="panel-note">Every promotion unlocks a new facility blueprint. Reach Boss rank to expand the HQ itself.</div></aside></div>`}
function baseView(){return `${head('Headquarters','A good operation starts with a good base. Spend credits to build yours.')}
<div class="rank-banner"><div><b>${rankName()} access clearance</b><div class="base-meta">${rankIndex()===5?'All construction permissions granted. Make this place yours.':'New blueprints arrive with every promotion.'}</div></div><span>${state.expansion>0?`EXPANSION LV. ${state.expansion}`:'KANTO HIDEOUT'}</span></div><div class="upgrade-list">${upgrades.map(u=>{const owned=state.owned.includes(u.id),locked=rankIndex()<u.rank,level=state.expansion,cost=u.expand?[180,320,500][level]||null:u.cost;return `<article class="upgrade ${owned?'owned':''} ${u.expand?'expansion':''}"><div class="upgrade-icon">${u.icon}</div><h3>${u.name}${u.expand&&level?` · LV. ${level}`:''}</h3><p>${u.expand?`Boss-only headquarters expansion. ${level===0?'Unlock a bigger footprint with a new wing.':`Your HQ has ${level} added wing${level===1?'':'s'}. Expand again to grow the operation.`}`:u.desc}</p><div class="upgrade-foot"><span>${owned&&!u.expand?'✓ INSTALLED':u.expand&&level>=3?'MAX EXPANSION':locked?`🔒 ${ranks[u.rank].name} rank`:u.start?'INCLUDED':`◈ ${cost} CR`}</span><button data-upgrade="${u.id}" ${locked||owned&&!u.expand||u.expand&&level>=3||state.credits<(cost||0)?'disabled':''}>${owned&&!u.expand?'Owned':locked?'Locked':u.expand&&level>=3?'Complete':state.credits<(cost||0)?'Need credits':u.expand?`Expand · ◈ ${cost}`: 'Install'}</button></div></article>`}).join('')}</div>
<div class="bottom-grid" style="margin-top:17px"><section class="base-card"><div class="section-title"><h2>Hideout overview</h2><span class="text-link">${state.owned.length} FACILITIES</span></div><div class="base-visual"><div class="mountain m1"></div><div class="mountain m2"></div><div class="base-building" style="width:${139+state.expansion*23}px;height:${82+state.expansion*9}px"></div><div class="base-lights"><i></i><i></i><i></i></div><div class="base-ground"></div></div><div class="base-info"><div><b>${state.expansion?'Expanded Rocket HQ':'Kanto Hideout'}</b><div class="base-meta">Expansion capacity ${state.expansion} / 3 · ${state.owned.filter(id=>id!=='quarters').length} upgrades installed</div></div><span>● SECURE</span></div></section><section class="activity-card"><div class="section-title"><h2>Why upgrade?</h2></div><div class="activity-item"><div class="activity-avatar">🎯</div><div class="activity-text"><b>Capture Lab</b> improves field capture odds.</div></div><div class="activity-item"><div class="activity-avatar">🛰️</div><div class="activity-text"><b>Intel Room</b> adds credits to every score.</div></div><div class="activity-item"><div class="activity-avatar">🏢</div><div class="activity-text"><b>HQ Expansion</b> is yours to shape at Boss rank.</div></div></section></div>`}
function roster(){return `${head('The collection','Every Pokémon you bring back makes Team Rocket stronger.')}
<div class="rank-banner"><div><b>${state.team.length} Pokémon secured</b><div class="base-meta">Your collection is proof of a career well played.</div></div><span>${rankName().toUpperCase()} RANK</span></div><div class="roster-grid">${state.team.length?state.team.slice().reverse().map((p,i)=>`<article class="pokemon-card"><span class="type-pill">${p.type}</span><img src="${sprite(p.id)}" alt="${esc(p.name)}"/><h3>${esc(p.name)}</h3><small>${p.mission} · #${String(state.team.length-i).padStart(3,'0')}</small></article>`).join(''):'<div class="empty-roster">No Pokémon secured yet.<br>Complete a field operation to start your collection.</div>'}</div>`}

input.newString:
function roster(){return `${head('The collection','Every Pokémon you bring back makes Team Rocket stronger.')}
<div class="rank-banner"><div><b>${state.team.length} Pokémon secured</b><div class="base-meta">Your collection is proof of a career well played.</div></div><span>${rankName().toUpperCase()} RANK</span></div><div class="roster-grid">${state.team.length?state.team.slice().reverse().map((p,i)=>`<article class="pokemon-card"><span class="type-pill">${p.type}</span><img src="${sprite(p.id)}" alt="${esc(p.name)}"/><h3>${esc(p.name)}</h3><small>${p.mission} · #${String(state.team.length-i).padStart(3,'0')}</small></article>`).join(''):'<div class="empty-roster">No Pokémon secured yet.<br>Complete a field operation to start your collection.</div>'}</div>`}
function encounterView(){const e=state.encounter;if(!e)return operations();const m=missions.find(x=>x.id===e.mission);if(e.step==='result'){const won=e.won;return `${head(won?'A new recruit!':'Target escaped',won?`${e.pokemon.name} is on the books. The boss will hear about this.`:'The target got away, but the operation isn’t a total loss.')}
<div class="encounter"><div class="encounter-top"><b>${m.name} · FIELD REPORT</b><span>${won?'CAPTURE CONFIRMED':'TARGET LOST'}</span></div><div class="result-panel"><div class="result-emoji">${won?'🎉':'💨'}</div><h2>${won?`${esc(e.pokemon.name)} secured!`:'They slipped away!'}</h2><p>${won?'Another Pokémon in Rocket hands. Keep building your reputation and the boss will notice.':'A tough target. Upgrade your capture gear or try a different approach next time.'}</p><div class="reward-pills"><span>◈ +${e.payout} CR</span>${won?`<span>♜ +1 CAPTURE</span><span>⬆ PROMOTION PROGRESS</span>`:'<span>FIELD EXPENSES COVERED</span>'}</div><button class="primary-btn" data-again="${m.id}">Back to assignments ↗</button></div></div>`}
const p=e.pokemon;const text=e.step==='approach'?'Choose how you want to approach the target.':e.step==='attack'?'Now weaken the target before you throw.':'Pick a capsule and make the capture.';return `${head('Field encounter',`${m.name} · ${m.place}`,'ACTIVE OPERATION · LIVE')}
<div class="view-grid"><section class="encounter"><div class="encounter-top"><b>${m.name}</b><span>● ENCOUNTER ACTIVE</span></div><div class="encounter-scene"><div class="battle-status"><b>${esc(p.name)}</b><small>WILD · ${p.type.toUpperCase()}</small><div class="hpbar"><i style="width:${e.hp}%"></i></div></div><img class="enemy" src="${sprite(p.id)}" alt="Wild ${esc(p.name)}"/><div class="player-status"><b>ROCKET CREW</b><div><small>${e.method?`APPROACH: ${e.method.toUpperCase()}`:'FIELD TEAM READY'}</small></div></div><img src="${sprite(52)}" alt="Your Meowth"/></div><div class="battle-log">${text}</div><div class="battle-actions">${e.step==='approach'?`<h4>Pick your approach</h4><div class="action-row"><button class="action-btn" data-approach="stealth">🥷 Stealth · improve capture odds</button><button class="action-btn" data-approach="distract">🪙 Distract · balanced play</button><button class="action-btn" data-approach="rush">⚡ Rush · heavy opening</button></div>`:e.step==='attack'?`<h4>Choose a field move</h4><div class="action-row"><button class="action-btn" data-attack="jab">Quick jab · 24 damage</button><button class="action-btn" data-attack="net">Rocket net · 42 damage</button></div>`:`<h4>Make your move</h4><div class="action-row"><button class="primary-btn" data-throw>Throw capture capsule · ${Math.round(odds(e)*100)}% estimated</button></div>`}</div></section><aside class="panel"><h3>Operation intel</h3><p class="panel-sub">Stay sharp. Every field choice shifts the odds.</p><div class="intel-row"><div class="intel-icon">🎯</div><div class="intel-copy"><b>Target rarity</b><small>${'★'.repeat(p.rarity)}${'☆'.repeat(5-p.rarity)} · ${['','Common','Uncommon','Rare','Very rare','Exceptional'][p.rarity]}</small></div></div><div class="intel-row"><div class="intel-icon">◈</div><div class="intel-copy"><b>Mission payout</b><small>Successful operation</small></div><span class="intel-value">${m.reward} CR</span></div><div class="intel-row"><div class="intel-icon">🧪</div><div class="intel-copy"><b>Capture gear</b><small>${state.owned.includes('gear')?'Lab optimized':'Standard capsule'}${state.owned.includes('training')?' · trained crew':''}</small></div><span class="intel-value">${state.owned.includes('gear')?'+12%':'—'}</span></div><div class="panel-note">${e.step==='approach'?'Stealth boosts the capture chance. A Rocket net does more damage; weakened targets are easier to secure.':'Weakened targets are easier to catch. Your capture chance appears on the capsule button.'}</div><button class="action-btn" style="width:100%;margin-top:13px" data-view="operations">Abort operation</button></aside></div>`}
function odds(e){return Math.max(.18,Math.min(.94,.47-e.pokemon.rarity*.052+(100-e.hp)*.0035+(e.bonus||0)+(state.owned.includes('gear')?.12:0)+(state.owned.includes('training')?.15:0)))}
function render(){const root=document.querySelector('#app');let content=state.view==='dashboard'?dashboard():state.view==='operations'?operations():state.view==='base'?baseView():state.view==='roster'?roster():encounterView();root.innerHTML=shell(content)}
function startMission(id){const m=missions.find(x=>x.id===id);if(!m||rankIndex()<m.rank)return;const p=m.pokemon[Math.floor(Math.random()*m.pokemon.length)];state.encounter={mission:id,pokemon:p,step:'approach',hp:100,bonus:0,method:'',won:false};state.view='encounter';render()}
function doThrow(){const e=state.encounter;if(Math.random()<odds(e)){e.won=true;state.captures++;const old=rankIndex();state.team.push({id:e.pokemon.id,name:e.pokemon.name,type:e.pokemon.type,mission:missions.find(m=>m.id===e.mission).name});const m=missions.find(m=>m.id===e.mission);e.payout=m.reward+e.pokemon.rarity*5+(state.owned.includes('intel')?10:0);state.credits+=e.payout;addActivity(`<b>${esc(e.pokemon.name)}</b> secured at ${m.name}. +${e.payout} credits.`,'◈');const now=rankIndex();if(now>old){addActivity(`Promotion earned — welcome to the ${rankName()} ranks.`,'♜');setTimeout(()=>toast(`Promotion! You are now a ${rankName()}. New base blueprints unlocked.`),300)}else toast(`${e.pokemon.name} secured! +${e.payout} credits.`)}else{e.won=false;e.payout=Math.max(8,Math.round(missions.find(m=>m.id===e.mission).reward*.35));state.credits+=e.payout;addActivity(`Operation complete at ${missions.find(m=>m.id===e.mission).name}; target escaped. +${e.payout} credits.`,'📡');toast('Target escaped. The crew recovered some field expenses.')};e.step='result';save();render()}
function handleClick(ev){const b=ev.target.closest('button');if(!b)return;if(b.dataset.view){state.view=b.dataset.view;if(b.dataset.view==='operations'&&state.encounter)state.encounter=null;save();render();return}if(b.dataset.mission){startMission(b.dataset.mission);return}if(b.dataset.approach){const e=state.encounter;e.method=b.dataset.approach;e.bonus=e.method==='stealth'?.17:e.method==='distract'?.08:0;e.hp=e.method==='rush'?77:100;e.step='attack';render();return}if(b.dataset.attack){const e=state.encounter;if(b.dataset.attack==='jab'){e.hp=Math.max(12,e.hp-24);e.bonus+=.025}else{e.hp=Math.max(8,e.hp-42);e.bonus+=.045}e.step='throw';render();return}if(b.hasAttribute('data-throw')){doThrow();return}if(b.dataset.again){state.encounter=null;state.view='operations';save();render();return}if(b.dataset.upgrade){const u=upgrades.find(x=>x.id===b.dataset.upgrade);if(!u||rankIndex()<u.rank)return;if(u.expand){if(state.expansion>=3)return;const cost=[180,320,500][state.expansion];if(state.credits<cost)return;state.credits-=cost;state.expansion++;addActivity(`Headquarters expanded to level ${state.expansion}.`,'🏢');toast(`HQ expansion complete · level ${state.expansion}`)}else{if(state.owned.includes(u.id)||state.credits<u.cost)return;state.credits-=u.cost;state.owned.push(u.id);addActivity(`${u.name} is now operational at HQ.`,'🔧');toast(`${u.name} installed at the hideout.`)}save();render()}}
document.querySelector('#app').addEventListener('click',handleClick);render();

